import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl View / JSX-like Component Syntax for JS Targets — design detail","description":"","frontmatter":{"title":"Handl View / JSX-like Component Syntax for JS Targets — design detail","type":"design","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","refs":["ADR-0117"]},"headers":[],"relativePath":"web/project/design/0117-handl-view-component-syntax.md","filePath":"vendored/web/project/design/0117-handl-view-component-syntax.md"}`),a={name:`web/project/design/0117-handl-view-component-syntax.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-view-jsx-like-component-syntax-for-js-targets-—-design-detail" tabindex="-1">Handl View / JSX-like Component Syntax for JS Targets — design detail <a class="header-anchor" href="#handl-view-jsx-like-component-syntax-for-js-targets-—-design-detail" aria-label="Permalink to “Handl View / JSX-like Component Syntax for JS Targets — design detail”">​</a></h1><p>Moved verbatim from ADR-0117 (ADR-0161 size budget). The ADR carries the rules; this page carries the context, tables, phases and trade-offs.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./0115-handl-sdkgen-dts-js.html">ADR-0115 — <code>.d.ts</code> SDKgen</a> will make JS frameworks reachable as low-level Handl arrows (<code>createElement</code>, <code>h</code>, <code>useState</code>, <code>ref</code>). That is verbose. <a href="./0116-handl-sfc-format.html">ADR-0116 — <code>.hfc</code> SFC Format</a> packages the view into a file with <code>&lt;template&gt;</code>, <code>&lt;script&gt;</code>, and <code>&lt;style&gt;</code>. This ADR defines the inline view syntax itself.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add a <code>view</code> block and XML-like tag syntax to Handl. It is parsed as an optional language surface and lowered to ordinary Handl arrows by the <code>component</code> transform pass.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><p>A <code>view</code> is a named arrow that returns a JS value:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>view Hello(name: String) {</span></span>
<span class="line"><span>  &lt;div&gt;</span></span>
<span class="line"><span>    &lt;h1&gt;Hello, {name}&lt;/h1&gt;</span></span>
<span class="line"><span>  &lt;/div&gt;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>component</code> transform lowers this to plain Handl:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Hello := (name) ~[JS]~&gt; Value</span></span>
<span class="line"><span>Hello = (name) ~&gt; do {</span></span>
<span class="line"><span>  h1 = createElement(&quot;h1&quot;, #{}, [&quot;Hello, &quot; ++ name])</span></span>
<span class="line"><span>  createElement(&quot;div&quot;, #{}, [h1])</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="lowering-rules" tabindex="-1">Lowering rules <a class="header-anchor" href="#lowering-rules" aria-label="Permalink to “Lowering rules”">​</a></h3><ul><li><code>&lt;tag&gt;</code> is sugar for <code>createElement(&quot;tag&quot;, attrs, children)</code> (or <code>h</code> for the Vue target).</li><li><code>&lt;Tag ...&gt;</code> is a component call; the tag must be a capitalized identifier that resolves to a Handl arrow.</li><li><code>attr=&quot;val&quot;</code> becomes <code>#{ attr: &quot;val&quot; }</code>.</li><li><code>attr={expr}</code> becomes <code>#{ attr: expr }</code>.</li><li><code>{expr}</code> inside a tag is text interpolation or a child expression.</li><li><code>v-if=&quot;cond&quot;</code> / <code>v-else</code> become ordinary <code>if</code>/<code>else</code>.</li><li><code>@event=&quot;handler&quot;</code> becomes an event attribute such as <code>#{ onClick: handler }</code>.</li><li>Capitalized tags are components; lowercase tags are host elements.</li><li>A <code>view</code> is just a named arrow, so it composes with ordinary Handl code.</li></ul><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to “Slots”">​</a></h3><p>Slots are explicit <code>&lt;slot&gt;</code> elements:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>view List(items) {</span></span>
<span class="line"><span>  &lt;ul&gt;</span></span>
<span class="line"><span>    &lt;slot name=&quot;item&quot; each={items} let:item&gt;</span></span>
<span class="line"><span>      &lt;li&gt;{item}&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/slot&gt;</span></span>
<span class="line"><span>  &lt;/ul&gt;</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>A default slot has no <code>name</code>.</li><li>Named slots use <code>name=&quot;...&quot;</code>.</li><li>Scoped slots use <code>let:</code> to name the data passed back and <code>each:</code> to iterate a list. The lowering is a Handl callback arrow.</li></ul><h3 id="reactive-state" tabindex="-1">Reactive state <a class="header-anchor" href="#reactive-state" aria-label="Permalink to “Reactive state”">​</a></h3><p>A <code>state</code> block declares component-local reactive state:</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>view Counter() {</span></span>
<span class="line"><span>  state count := 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;button onClick={() ~&gt; count := count + 1}&gt;</span></span>
<span class="line"><span>    {count}</span></span>
<span class="line"><span>  &lt;/button&gt;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>component</code> transform turns <code>state</code> into the target&#39;s reactivity call (<code>useState</code> for React, <code>ref</code>/<code>reactive</code> for Vue, stores for Svelte).</p><h3 id="target-binding" tabindex="-1">Target binding <a class="header-anchor" href="#target-binding" aria-label="Permalink to “Target binding”">​</a></h3><p>The transform is target-agnostic. A compile-time <code>target</code> config picks the runtime calls:</p><ul><li><code>target = &quot;react&quot;</code> → <code>createElement</code>, <code>useState</code>, etc.</li><li><code>target = &quot;vue&quot;</code> → <code>h</code>, <code>ref</code>, <code>reactive</code>, <code>render_slot</code>, etc.</li><li><code>target = &quot;svelte&quot;</code> → Svelte runtime calls or <code>.svelte</code> source output.</li><li><code>target = &quot;dom&quot;</code> → <code>document.createElement</code>, <code>document.body.append</code>.</li></ul><p>This is equivalent to the JSX factory setting in TypeScript, but extended to multiple target frameworks.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The <code>component</code> pass is a pure <code>Ast → Ast</code> transform and can be previewed, traced, or disabled via <code>hnl transform component</code>.</li><li>SFC packaging is handled separately in ADR-0116.</li><li>The syntax is small and not framework-specific; adding Astro, Svelte, or Solid later is a new <code>target</code> adapter, not new grammar.</li><li>Out of scope for the first version: framework-specific lifecycle hooks (<code>onMounted</code>, <code>onUnmounted</code>, <code>useEffect</code>).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0094-generic-ast-transform-engine.html">ADR-0094 — Generic AST Transform Engine</a></li><li><a href="./0114-handl-compile-plugin-architecture.html">ADR-0114 — Handl Compile Plugin</a></li><li><a href="./0115-handl-sdkgen-dts-js.html">ADR-0115 — Handl SDK Generator: TypeScript Declaration Backend</a></li><li><a href="./0116-handl-sfc-format.html">ADR-0116 — Handl Single-File Component Format</a></li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};